const quiltVariants=[
  {id:'winter',name:'冬被',hint:'蓬松厚实 · 分仓绗缝 · 柔软有体积',spec:'被芯类别为冬被：单件厚实蓬松被芯，较大方格分仓绗缝，填充饱满、缝线轻微下陷，窄包边，折叠柔软有厚度；不是薄夏被，配拍2只枕套，无被套或套件床单。'},
  {id:'summer',name:'夏凉被',hint:'轻薄贴合 · 细密绗缝 · 浅褶自然垂落',spec:'被芯类别为夏凉被：单件轻薄低蓬松夏被，细密菱格绗缝，薄窄包边，贴合床面，柔软浅褶与轻薄垂落；不是厚冬被，配拍2只枕套，无被套或套件床单。'}
];
function currentQuiltVariant(){return quiltVariants.find(v=>v.id===state.quiltSeason)||quiltVariants[0]}
function quiltVariantSpecification(){return currentQuiltVariant().spec}
function quiltVariantNotes(){return ' 被芯季节以规格中的'+currentQuiltVariant().name+'为准，季节是被芯结构要求。面料质感只控制外壳织纹与光泽，不改变填充厚度。A花型用于正面，B用于反面；只上传A则两面均用A。翻折为同一条被芯的柔软宽折，接触床面；保持所选季节厚度。枕套正面A、反面B；仅A时枕套全部A。不复制示例的白色。'}
function quiltAngleName(angle){return angle.id==='pillowclose'?'包边特写':angle.name}
const quiltVariantPanel=document.createElement('section');quiltVariantPanel.id='quiltVariantPanel';quiltVariantPanel.className='set-variant-flyout quilt-variant-flyout';quiltVariantPanel.hidden=true;quiltVariantPanel.setAttribute('aria-labelledby','quiltVariantTitle');
quiltVariantPanel.innerHTML='<div class="set-variant-heading"><div><h2 id="quiltVariantTitle">被芯</h2><p>选择季节厚度 · 默认冬被</p></div><button type="button" class="set-variant-close" aria-label="收起被芯分类">×</button></div><div class="set-variant-options"><h3>被芯类别</h3><div class="set-variant-grid" role="group" aria-label="被芯类别"></div></div><div class="set-variant-footer"><span id="quiltVariantSelected"></span><button type="button" class="set-variant-done">完成选择</button></div>';
document.body.append(quiltVariantPanel);
function renderQuiltVariantControl(){const trigger=document.querySelector('[data-product="quilt"]');if(trigger){trigger.classList.add('has-quilt-variants');trigger.setAttribute('aria-expanded',String(!quiltVariantPanel.hidden));trigger.setAttribute('aria-controls','quiltVariantPanel');trigger.title=currentQuiltVariant().name+' · 点击展开被芯分类';renderChosenProductLabel(trigger,'被芯',currentQuiltVariant().name);}if(state.product==='quilt'){$('partsHint').textContent='1 件'+currentQuiltVariant().name+' + 2 只配套枕套 · '+currentQuiltVariant().hint;document.querySelector('.group-angles .group-purpose').textContent=currentQuiltVariant().name+'构图 · 可多选';}else if(state.product!=='sheet')document.querySelector('.group-angles .group-purpose').textContent='选择构图 · 可多选';quiltVariantPanel.querySelector('#quiltVariantSelected').textContent='已选：'+currentQuiltVariant().name;}
function closeQuiltVariants(returnFocus=false){quiltVariantPanel.hidden=true;renderQuiltVariantControl();if(returnFocus)document.querySelector('[data-product="quilt"]')?.focus()}
function placeQuiltVariants(){placeProductSubmenu(quiltVariantPanel,document.querySelector('[data-product="quilt"]'),510);}
function selectQuiltVariant(id){if(state.busy||state.product!=='quilt'||!quiltVariants.some(v=>v.id===id))return;(state.productVariantChoices??={}).quilt=true;state.quiltSeason=id;quiltVariantPanel.querySelectorAll('[data-quilt-variant]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.quiltVariant===id)));renderQuiltVariantControl();renderSelections();if(typeof closeQuiltVariants==='function')closeQuiltVariants(true);}
function openQuiltVariants(){if(state.busy||state.product!=='quilt')return;const grid=quiltVariantPanel.querySelector('.set-variant-grid');grid.replaceChildren();for(const item of quiltVariants){const button=document.createElement('button');button.type='button';button.className='set-variant-option illustrated-variant-option';button.dataset.quiltVariant=item.id;button.setAttribute('aria-pressed',String(currentQuiltVariant().id===item.id));const picture=document.createElement('span');picture.className='product-variant-preview';picture.style.backgroundImage="url('/assets/quilt-"+item.id+"-angles-v3-framed.png')";picture.setAttribute('role','img');picture.setAttribute('aria-label',item.name+' AI 结构示例');const name=document.createElement('strong');name.textContent=item.name;const hint=document.createElement('small');hint.textContent=item.hint;button.append(picture,name,hint);button.addEventListener('click',()=>selectQuiltVariant(item.id));grid.append(button)}quiltVariantPanel.hidden=false;placeQuiltVariants();renderQuiltVariantControl();}
quiltVariantPanel.querySelector('.set-variant-close').onclick=()=>closeQuiltVariants(true);quiltVariantPanel.querySelector('.set-variant-done').onclick=()=>closeQuiltVariants(true);
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product&&!state.busy){if(product.dataset.product==='quilt'){if(quiltVariantPanel.hidden)openQuiltVariants();else closeQuiltVariants()}else closeQuiltVariants();renderQuiltVariantControl();return;}if(!quiltVariantPanel.contains(e.target))closeQuiltVariants();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!quiltVariantPanel.hidden)closeQuiltVariants(true);if(e.key==='ArrowDown'&&e.target.closest('[data-product="quilt"]')&&!state.busy){e.preventDefault();openQuiltVariants();quiltVariantPanel.querySelector('[aria-pressed=true]')?.focus();}});
window.addEventListener('resize',()=>closeQuiltVariants());window.addEventListener('scroll',e=>{if(!quiltVariantPanel.contains(e.target))closeQuiltVariants()},{passive:true,capture:true});
new MutationObserver(renderQuiltVariantControl).observe($('products'),{childList:true});new MutationObserver(()=>{if(state.busy)closeQuiltVariants();renderQuiltVariantControl()}).observe($('generateBtn'),{attributes:true,attributeFilter:['disabled']});renderQuiltVariantControl();
